import{_ as s,o as a,c as t,ag as i}from"./chunks/framework.D1z9wg1y.js";const k=JSON.parse('{"title":"Setup on Linux","description":"","frontmatter":{},"headers":[],"relativePath":"setup-linux.md","filePath":"setup-linux.md"}'),n={name:"setup-linux.md"};function h(o,e,d,r,p,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="setup-on-linux" tabindex="-1">Setup on Linux <a class="header-anchor" href="#setup-on-linux" aria-label="Permalink to &quot;Setup on Linux&quot;">​</a></h1><p>This page sets up a Linux machine in four steps: the prerequisites, the clone, <code>harness setup</code> and the check that it worked. <code>harness setup</code> puts the tools and the <a href="./concepts#frontend">frontends</a> that you choose on the machine, and then sets up the harness, with its <a href="./concepts#install">install</a>. <a href="./setup-reference">setup-reference.md</a> gives each step of <code>harness setup</code>: what it does, why, and how to do it by hand. <a href="./setup-macos">setup-macos.md</a> is the page for macOS.</p><p><code>harness setup</code> runs on Ubuntu, and the steps are checked on Ubuntu 26.04 only, on <code>x86_64</code> and <code>aarch64</code> (64-bit Arm). They use <code>~/Research/Harness</code> as the path of the checkout. <a href="./concepts">Introduction</a> explains the terms that this page uses, and the glossary there has an entry for each.</p><h2 id="the-prerequisites" tabindex="-1">The prerequisites <a class="header-anchor" href="#the-prerequisites" aria-label="Permalink to &quot;The prerequisites&quot;">​</a></h2><p><code>harness setup</code> needs Python 3.14 and git, and the installers that it runs need curl. This line installs them, and it needs an administrator, a user who may run <code>sudo</code>. Without <code>sudo</code>, ask an administrator to run it for you:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apt-get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3-venv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> curl</span></span></code></pre></div><p>Ubuntu 26.04 packages no uv: the first run of <code>harness</code> fetches the uv release that it pins. <a href="./dependencies#you-provide">Dependencies</a> says why each one is a prerequisite.</p><h2 id="the-clone" tabindex="-1">The clone <a class="header-anchor" href="#the-clone" aria-label="Permalink to &quot;The clone&quot;">​</a></h2><p>These commands clone the harness repository and put its <code>bin/</code> directory on the <code>PATH</code>, so that your shell finds the command <code>harness</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/michakraus/ResearchHarness.git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Research/Harness</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/Research/Harness/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Add the <code>export</code> line to your shell startup file too, <code>~/.bashrc</code> for bash or <code>~/.zshrc</code> for zsh, so that each new shell finds <code>harness</code>. The first run of <code>harness</code> outside a <a href="./concepts#session">session</a> fetches uv into <code>~/.local/bin</code>, checks its sha256, makes the Python environment of the harness with <code>uv sync</code>, and names it in one line; in a session, its line names <code>harness install --apply</code>, which makes it. A Python older than 3.14 stops <code>harness</code> with exit status 2, an error that names the version found. This line lists the subcommands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><h2 id="harness-setup" tabindex="-1"><code>harness setup</code> <a class="header-anchor" href="#harness-setup" aria-label="Permalink to &quot;\`harness setup\`&quot;">​</a></h2><p>Run <code>harness setup</code> in your own terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/Research/Harness/bin/harness setup</span></span></code></pre></div><p>Without a <a href="./concepts#profile">profile</a>, it copies the example profile and asks for the keys that have no default: <code>memory_project</code>, <code>tree_agents</code>, <code>org</code>, <code>repository_roots</code> and <code>leak</code>. An empty answer keeps the example&#39;s value. Then it asks for the frontends and the components, each from a numbered list, and whether this machine develops the harness. It writes the answers into <code>[setup]</code> of the profile, shows its plan, and runs the plan after y/N: the directories, one <code>sudo apt-get install -y</code> line, the pinned releases, the installers of the projects, <code>harness install --apply</code>, <code>git config core.hooksPath .githooks</code>, <code>harness trust --apply</code>, the jobs and the Kaimon token where <code>[setup]</code> chooses their components, and <code>harness doctor</code>. <a href="./setup-reference">setup-reference.md</a> has a section for each step.</p><p>Two options change the run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # print every command of the plan, and change nothing</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # read [setup] of the profile, and ask nothing</span></span></code></pre></div><p><strong>When a step fails</strong>, <code>harness setup</code> prints its output and stops with exit status 2. Fix the cause, then run <code>harness setup</code> again: it plans again and skips what is done. Without <code>sudo</code>, or when <code>sudo -n true</code> is refused, it prints the <code>apt-get</code> line for an administrator and stops there: run <code>sudo -v</code> first, or have an administrator run the line. The step <code>harness trust --apply</code> needs <code>~/.claude.json</code>, which Claude Code writes at its first start: start <code>claude</code> once, or, where <code>[setup]</code> does not choose <code>claude</code>, run <code>echo {} &gt; ~/.claude.json</code>.</p><p><strong>By hand.</strong> <code>harness setup</code> prints the steps that it cannot do under <em>By hand</em>, before its last step: with <code>iterm</code>, a default, that iTerm2 runs on macOS only; with <code>jobs</code>, the lingering line for an administrator; with <code>opencode</code>, the <code>PATH</code> line of <code>~/.opencode/bin</code>; with <code>antigravity</code>, the Antigravity app; and each tool with no package, release or installer. Add these lines to your shell startup file, so that each new shell finds the programs of the three directories:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.local/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.julia/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PATH</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/.opencode/bin:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>Over SSH, log in <code>gh</code> and Claude Code as <a href="./setup-reference#a-machine-reached-over-ssh">A machine reached over SSH</a> says.</p><h2 id="the-check-that-it-worked" tabindex="-1">The check that it worked <a class="header-anchor" href="#the-check-that-it-worked" aria-label="Permalink to &quot;The check that it worked&quot;">​</a></h2><p>The last step of <code>harness setup</code> is <code>harness doctor</code>. It checks the machine, the tools, the profile, the install and the jobs, read-only, and prints one line for each check: <code>PASS</code>, <code>WARN</code>, <code>FAIL</code> or <code>SKIP</code>. A <code>FAIL</code> line names the section of <a href="./setup-reference">setup-reference.md</a> that fixes it. Run it again after each fix, in a plain terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>It exits with status 0 when no check fails, and 1 when one fails. Then run the harness&#39;s own test cases. The last line gives the number of cases, and it must say <code>0 wrong</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">harness</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>At the start of each new Claude Code or Antigravity session, a <a href="./concepts#hook">hook</a> compares <code>~/.claude/</code> with the sources. When a source changed after the last install, the session starts with a warning about <a href="./concepts#drift">drift</a>. The <a href="./tutorial">tutorial</a> starts your first session.</p><p><strong>More.</strong> To keep several machines the same, see <a href="./setup-reference#dotfiles-optional">Dotfiles (optional)</a>.</p>`,29)])])}const u=s(n,[["render",h]]);export{k as __pageData,u as default};
